"use client";

import { motion } from "motion/react";
import { site } from "@/data/site";

const field =
  "mt-2 w-full border border-white/70 bg-transparent px-3 py-2.5 text-sm outline-none transition-colors focus:border-accent";

/**
 * 联系表单。网站目前没有后端，点 Send 会用访客的邮件软件打开一封填好内容的邮件。
 * 以后想直接收表单，可以接 Formspree / Resend 等服务。
 */
export default function ContactForm() {
  function onSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const f = new FormData(e.currentTarget);
    const name = `${f.get("first")} ${f.get("last")}`.trim();
    const body = `${f.get("message")}\n\n— ${name} (${f.get("email")})`;
    window.location.href = `mailto:${site.email}?subject=${encodeURIComponent(
      `Portfolio enquiry from ${name}`,
    )}&body=${encodeURIComponent(body)}`;
  }

  return (
    <motion.form
      onSubmit={onSubmit}
      initial={{ opacity: 0, y: 24 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.6 }}
      className="w-full max-w-sm text-sm"
    >
      <h1 className="mb-6">Contact us</h1>
      <div className="grid grid-cols-2 gap-3">
        <label>
          First name *
          <input name="first" required className={field} />
        </label>
        <label>
          Last name
          <input name="last" className={field} />
        </label>
      </div>
      <label className="mt-5 block">
        Email *
        <input name="email" type="email" required className={field} />
      </label>
      <label className="mt-5 block">
        Message
        <textarea name="message" rows={4} className={`${field} resize-none`} />
      </label>
      <button
        type="submit"
        className="mt-6 bg-accent px-12 py-2.5 transition-colors hover:bg-white hover:text-accent active:scale-95"
      >
        Send
      </button>
    </motion.form>
  );
}
